def add_equipment_master_data(apps, schema_editor):

    Item = apps.get_model(
        "inventory",
        "Item",
    )

    Equipment = apps.get_model(
        "inventory",
        "Equipment",
    )

    for data in EQUIPMENT_DATA:

        (
            name,
            rank,
            slot,
            style,
            base_battle_power,
            strength_rate,
            intelligence_rate,
            dexterity_rate,
            agility_rate,
            vitality_rate,
            luck_rate,
        ) = data

        # ----------------------------------------------------
        # Itemマスター
        # ----------------------------------------------------

        item, _ = Item.objects.update_or_create(
            name=name,
            defaults={
                "description": (
                    f"{rank}ランクの"
                    f"{'物理型' if style == 'physical' else '魔法型'}装備。"
                ),
                "category": "equipment",

                # 値段は後でバランス調整
                "buy_price": 0,
                "sell_price": 0,

                "is_usable": False,

                # 現時点ではNPC販売しない
                "npc_purchasable": False,

                # 売却・フリマは可能
                "npc_sellable": True,
                "market_sellable": True,
            },
        )

        # ----------------------------------------------------
        # Equipmentマスター
        # ----------------------------------------------------

        Equipment.objects.update_or_create(
            item=item,
            defaults={
                "rank": rank,
                "slot": slot,
                "style": style,
                "base_battle_power": base_battle_power,

                "strength_rate": strength_rate,
                "intelligence_rate": intelligence_rate,
                "dexterity_rate": dexterity_rate,
                "agility_rate": agility_rate,
                "vitality_rate": vitality_rate,
                "luck_rate": luck_rate,
            },
        )


